#include "MigrationRuntime.hpp"
#include <cmath>
namespace elysium::fortress {bool MigrationRuntime::add(Arrival a,std::string&w){if(!a.id||!a.origin){w="invalid arrival";return false;}return rows_.emplace(a.id,std::move(a)).second;}MigrationDecision MigrationRuntime::evaluate(const MigrationFactors&f,double t)const{MigrationDecision d;auto add=[&](const char*n,double v){v=std::clamp(std::isfinite(v)?v:0.0,-1.0,1.0);d.reasons.push_back({n,v});d.score+=v;};add("reputation",f.reputation);add("safety",f.safety);add("wealth",f.wealth);add("institutions",f.institutions);add("relations",f.relations);add("housing",f.housing);add("food",f.food);add("threat",-f.threat);add("policy",f.policy);d.eligible=d.score>=t;return d;}bool MigrationRuntime::promote(StableId id,LegalStatus s,std::string&w){auto i=rows_.find(id);if(i==rows_.end()){w="unknown arrival";return false;}i->second.legal=s;return true;}}
